for line in lines:
    matched_fr = False
    for prefix, rep in fr_replacements.items():
        if line.startswith(prefix):
            updated_lines.append(rep + "\n")
            matched_fr = True
            break
    if matched_fr:
        continue

    if line.startswith('| **01** | **SS1:'):
        updated_lines.append(table_17_rows + "\n")
        skip_table = True
        continue
    if skip_table:
        if line.startswith('### Thống kê tổng hợp'):
            skip_table = False
            updated_lines.append(line)
        continue
    updated_lines.append(line)

final_text = "".join(updated_lines)
with open('docs/requirements-analysis.md', 'w', encoding='utf-8') as f:
    f.write(final_text)

